import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as i,a as o,b as n,c as s}from"./chunks/M-S-US6a.BRwbLMSt.js";import{_ as l,o as r,c as d,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Update","description":"","frontmatter":{},"headers":[],"relativePath":"use/update.md","filePath":"use/update.md"}'),u={name:"use/update.md"};function c(h,e,m,g,f,b){return r(),d("div",null,[...e[0]||(e[0]=[p('<p>You can update xDrip by installing another version on top of the current one without uninstalling it, the same way you originally <a href="./../install/download.html">installed</a> it.</p><p>You can also use the xDrip internal update mechanism.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> Update settings</p></div><p>Update settings allow you to choose which xDrip versions you are offered as updates.</p><div class="warning custom-block"><p class="custom-block-title">DO NOT UNINSTALL xDRIP+</p><p>You can upgrade and downgrade xDrip just by installing a newer or an older version on top of the current one.<br> Uninstalling xDrip might lead to complete and unrecoverable data loss if you don&#39;t <a href="./../troubleshoot/reinstall.html#reinstall-xdrip">back up</a>.</p></div><p>Only xDrip official versions can use this feature.<br> If you installed a <a href="./../install/download.html#forked-versions">forked version</a>, only the author can provide upgrades.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Updating xDrip is completely transparent and will not require any specific actions on your current sensor.<br> Your settings will be maintained unless a serious modification was made on a specific setting.<br> As a precaution it&#39;s better to keep xDrip monitored if you selected an alpha or nightly release.</p></div><p>You should enable automatic update check.</p><div class="admonition xdripitem"><p class="admonition-title">Automatic update check <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Get notified of new apk releases</p></div><p>If you leave it disabled xDrip will remind you to update every 60 days.</p><div class="admonition xdripitem"><p class="admonition-title">Hey Fam...</p><p> You have update checks switched off!<br>  We try to fix bugs and add new features to xDrip over time.<br>  Every 60 days this reminder will appear to ask you to turn update checking on.</p></div><p>There are three update channels:</p><ul><li>Stable: released versions that proved stability and reliability</li><li>Beta: versions that are candidates to stable release</li><li>Alpha: versions in development</li></ul><p>A fourth one only appears once Alpha has been selected (see <a href="#getting-the-nightlies-on-automatic-update">below</a>):</p><ul><li>Nightly: prototypes for testing</li></ul><p>Most tested versions will not include the latest features and fixes.</p><p>Less tested versions might include bugs but will also include the latest features and fixes.</p><div class="admonition xdripitem"><p class="admonition-title">Update Channel</p><p> Choose Stable, Beta or Alpha releases</p></div><div class="admonition xdripitem"><p class="admonition-title">Update Channel</p><p> Stable - tried and tested versions<br>  Beta - new features but not fully tested<br>  Alpha - versions for early testing<br>  Nightly - untested raw code - experts only!</p></div><h3 id="getting-the-nightlies-on-automatic-update" tabindex="-1">Getting the nightlies on automatic update <a class="header-anchor" href="#getting-the-nightlies-on-automatic-update" aria-label="Permalink to &quot;Getting the nightlies on automatic update&quot;">​</a></h3><p>The Nightly channel is hidden until you have selected Alpha once.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> Update settings<br>   Update Channel</p></div><ol><li>Open Update Channel. If Nightly is in the list, select it and you&#39;re done.</li><li>If Nightly isn&#39;t listed, select Alpha, go back to the xDrip home screen, then open xDrip Update Settings and Update Channel again. Nightly is now visible: select it.</li></ol><div class="warning custom-block"><p class="custom-block-title">Nightly is the least tested channel</p><p>Nightly builds contain the newest and least tested code. They are the first to receive new features, but also where bugs are usually uncovered. Keep an eye on xDrip after each update, and be ready to <a href="#downgrade">downgrade</a> by installing an older release on top.</p></div><p>Update checks happen roughly every 24 hours. To check immediately, use <a href="./3dotsmenu.html#check-for-updated-version">Check for Update</a> in the 3 dots menu.</p><p>Looking in the <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">official repository</a>, you can identify the latest release by the label Latest.<br> You can download the latest release <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">here</a>.<br> All others are labelled Pre-release.</p><img src="'+i+'" style="zoom:75%;"><p>Reporting features are not used anymore. If you need support use <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussions</a> or <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Automatic crash reporting</p></div><div class="admonition xdripitem"><p class="admonition-title">Enable telemetry</p></div><p>Feedback is not used anymore. Only use it for compliments.</p><div class="admonition xdripitem"><p class="admonition-title">Send feedback message</p></div><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h3><p>You can update xDrip by installing another version on top of the current one without uninstalling it, the same way you originally <a href="./../install/download.html">installed</a> it.</p><p>You can also use the xDrip internal update mechanism.</p><p>Update available notifications will trigger based on your channel selection.<br> You can manually request a check if you disabled automatic update check using the <a href="./3dotsmenu.html#check-for-updated-version">3 dots menu</a>.</p><ol><li>The current update channel will be displayed</li><li>Current and newer (available) versions</li><li>Download now will start the update download, Android will ask for the install authorization when download is complete.</li><li>You can disable automatic updates. This has the same effect as the automatic update check button above.</li><li>If you don&#39;t use the internal downloader, your device will use the default app for downloading internet files.</li><li>Exit without doing anything.</li></ol><img src="'+o+'" style="zoom:75%;"><p>If selecting the internal downloader you will see a progress bar and once complete, the install will start automatically.</p><img src="'+n+'" style="zoom:75%;"><p>If you didn&#39;t select the internal downloader your phone will download the package from <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a> and launch the install once complete.</p><p>No new permissions should be required.</p><img src="'+s+'" style="zoom:75%;"><p>Once upgraded you can verify the current version in <a href="./../troubleshoot/systemstatus.html">system status</a>.</p><h3 id="downgrade" tabindex="-1">Downgrade <a class="header-anchor" href="#downgrade" aria-label="Permalink to &quot;Downgrade&quot;">​</a></h3><p>You don&#39;t need to uninstall xDrip to return to an older version (unless <a href="./../troubleshoot/reinstall.html">switching from official to forked version</a> and the other way round): just install the version you want on top of the current one <a href="./../install/download.html">like you did at first install</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',48)])])}const k=l(u,[["render",c]]);export{x as __pageData,k as default};
